  sources.programming={title:'Haas — программирование токарного станка, X/Z и U/W',url:'https://haascnc.com/service/online-operator-s-manuals/lathe-operator-s-manual/lathe---programming.html',note:'Английский; соглашения конкретного токарного управления. В учебном редакторе реализована только часть команд.'};
  sources.rapid={title:'Haas — G00, быстрое позиционирование',url:'https://haascnc.com/service/codes-settings.type=gcode.machine=lathe.value=G00.html',note:'Английский; реальная траектория быстрого хода зависит от движения осей.'};
  articles.push({id:'gcode-start',category:'program',title:'Первые программы: от слова к траектории',lead:'Не заучивайте строку целиком: объясните действие каждого слова и сохранённый режим.',lessons:['axes','modal','incremental'],sources:['programming','rapid'],tags:['G-код','M-код','G21','G18','G97','G98','G99','F','S','редактор','программа'],sections:[
    section('Сначала выберите соглашения',['В новом блоке G-кода используется ограниченная токарная модель по материалам Haas. Размеры заданы в миллиметрах, X — по диаметру, Z — вдоль оси детали. Торец принят за Z0; рабочая часть заготовки находится в отрицательной области Z. Начальная точка каждого задания дана явно. Это позволяет проследить движение без изучения наладки реального инструмента.','X/Z в рассматриваемом токарном соглашении задают абсолютные положения. Например, из Z−5 команда Z−12 ведёт в точку −12, то есть меняет координату на −7 мм. Адреса U/W для приращений не включены в учебный редактор. Не переносите сюда фрезерные правила G90/G91: у токарного Haas G90 — цикл точения.']),
    section('Читайте слова и единицы',['В G01 X28 Z−18 F0.1 действие задаёт G01, конечную точку — X28 и Z−18, подачу — F0.1. В самом редакторе используйте обычный знак минуса и десятичную точку. Программа читается по строкам сверху вниз; круглые скобки содержат комментарий и не вызывают движение.','G99 при выбранных миллиметрах задаёт подачу на оборот; G98 — подачу в минуту. Поэтому сначала найдите действующие единицы, затем читайте число F. Слова подачи и оборотов могут быть записаны раньше нужного движения: отсутствие повторного F не означает нулевую подачу.']),
    section('Проследите смену состояния',['После G01 Z-8 F0.1 строка X26 сохраняет линейный режим и подачу; меняется только X. После G00 Z3 следующая строка X36 сохранит быстрое позиционирование. Чтобы перейти к рабочему ходу, нужно снова выбрать G01. Добавление F в G00 не меняет тип движения.','G97 задаёт режим постоянных оборотов, S — их значение. M03 включает вращение, M05 останавливает его, M30 завершает программу. В заданиях остановку показывают отдельной M05 перед концом. Чтение этих команд не означает, что учебные обороты подходят выбранному материалу.']),
    section('Как проверить себя в редакторе',['Сначала разберите готовый пример по строкам, затем перейдите к другому условию и измените черновик. Нажатие «Разобрать код» показывает состояния и сообщения о строках, но не засчитывает задание. Зачёт даёт отдельная проверка требуемого маршрута. Сохраняются и черновик, и последнее корректное решение.','Зелёные точки задают цель, янтарные отрезки показывают G01, голубой пунктир — условное соединение конечных точек G00. Настоящий быстрый ход не обязан быть такой прямой. Отсутствие предупреждения на схеме не доказывает отсутствие столкновения: форма инструмента, патрон и реальный съём металла здесь не рассчитываются.'],['Объясните, что изменится в каждой строке.','Проверьте единицы F и действующий G00/G01.','Сравните все промежуточные точки с заданием.','Отделяйте учебную траекторию от производственной программы.'])]});
  glossary.push({term:'G-код',definition:'Команда подготовительной функции ЧПУ; смысл номера зависит от диалекта и оборудования.',article:'gcode-start'},{term:'M-код',definition:'Команда вспомогательной функции, например включения или остановки шпинделя в выбранном управлении.',article:'gcode-start'},{term:'Блок программы',definition:'Строка с совместно интерпретируемыми словами, например действием, координатами и подачей.',article:'gcode-start'},{term:'Линейная интерполяция',definition:'Согласованное движение осей по прямой к заданной конечной точке; в блоке изучается команда G01.',article:'gcode-start'});
  articles.push(...content.articles);glossary.push(...content.glossary);
