  const normalize=text=>String(text||'').toLowerCase().replace(/ё/g,'е').trim();
  function text(article){const fig=figures[article.visual];return [article.title,article.lead,...(article.outcome?[article.outcome]:[]),...(fig?[fig.caption,...fig.legend]:[]),...article.sections.flatMap(s=>[s.title,...s.paragraphs,...s.bullets,...(s.table?[s.table.caption,s.table.headers.join(' | '),...s.table.rows.map(row=>row.join(' | '))]:[])]),...(article.checks?.length?['Проверьте понимание',...article.checks.flatMap(c=>[c.prompt,'Ответ: '+c.answer,c.reason])]:[])].join('\n\n');}
  function minutes(article){return Math.max(1,Math.ceil(text(article).split(/\s+/).length/140));}
  function search({query='',category='all',filter='all'}={},state=restore(null)){
    state=restore(state);
    const terms=normalize(query).split(/\s+/).filter(Boolean);
    return articles.filter(a=>(category==='all'||a.category===category)&&(filter!=='read'||state.read.includes(a.id))&&(filter!=='bookmarks'||state.bookmarks.includes(a.id))&&terms.every(q=>normalize(text(a)+' '+a.tags.join(' ')+' '+a.sources.map(id=>sources[id].title).join(' ')).includes(q)));
  }
