  function toggle(state,id,field){if(!['read','bookmarks'].includes(field)||!articles.some(a=>a.id===id))throw new Error('Неизвестная статья или отметка.');const next=restore(state);next[field]=next[field].includes(id)?next[field].filter(x=>x!==id):[...next[field],id];return next;}
  function lessonArticles(id){return articles.filter(a=>a.lessons.includes(id));}
  function exportText(article){return norms.textForArticle(article.id)+'\n\n'+text(article)+'\n\nДополнительное чтение:\n'+article.sources.map(id=>sources[id].title+'\n'+sources[id].url+'\n'+sources[id].note).join('\n\n');}
  function readingPath(id){return paths.find(p=>p.id===id)||null;}
  function pathArticles(id){return (readingPath(id)?.articles||[]).map(key=>articles.find(a=>a.id===key));}
  function relatedArticles(article,pathId=''){const route=readingPath(pathId),at=route?.articles.indexOf(article.id)??-1;if(at>=0)return pathArticles(pathId).slice(at+1,at+3);return (article.related||articles.filter(a=>a.id!==article.id&&a.category===article.category).slice(0,3).map(a=>a.id)).map(id=>articles.find(a=>a.id===id));}
